// Fit game menus into the viewport; primary actions stay outside the content area.
function fitMenu(){$('quarters').style.zoom='1';}


function completeRun(){if(g.arena){if(arenaMapChoice==='rotation')arenaRotation++;active=false;paused=false;mouse.fire=mouse.ads=false;showScreen('arenaResults');return;}const reward=settleRun(profile,g);saveProfile();active=false;paused=false;mouse.fire=false;mouse.ads=false;if(!reward){showScreen('hub');return;}lastReward=reward;lastResultGame=g;showScreen('results');}

// Legacy district links arrive at the same operation menu, with no second game shell.
if(new URLSearchParams(location.search).get('mode')==='district'){introShowing=false;$('cinematic').classList.add('hidden');$('cinematic').classList.remove('menuOpening');$('overlay').style.opacity='';showScreen('districtMenu');}
